-- Canonical SPIKE Policy Core snapshot for reproducible project deployments.
create table if not exists public.spike_policy_rules (id text primary key, version integer not null default 1, category text not null, title text not null, summary text not null default '', severity text not null default 'medium' check (severity in ('low','medium','high','critical')), enforcement text not null default 'review' check (enforcement in ('allow','warn','review','remove','restrict','suspend','terminate')), active boolean not null default true, priority integer not null default 100, body jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.spike_policy_versions (id uuid primary key default gen_random_uuid(), policy_id text not null references public.spike_policy_rules(id) on delete cascade, version integer not null, snapshot jsonb not null, published_at timestamptz, created_at timestamptz not null default now(), unique(policy_id,version));
alter table public.spike_policy_rules enable row level security; alter table public.spike_policy_versions enable row level security;
revoke all on public.spike_policy_rules,public.spike_policy_versions from anon,authenticated;
grant select on public.spike_policy_rules,public.spike_policy_versions to authenticated;
drop policy if exists "spike policy rules readable" on public.spike_policy_rules; create policy "spike policy rules readable" on public.spike_policy_rules for select to authenticated using(active=true);
drop policy if exists "spike policy versions readable" on public.spike_policy_versions; create policy "spike policy versions readable" on public.spike_policy_versions for select to authenticated using(true);
