insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-CONTENT-004',1,'Content','Hateful conduct POL-CONTENT-001Attacks, dehumanization or calls for harm targeting people because of protected characteristics are prohibited. Discussion, criticism, reporting or educational context can require contextual review.Targeted harassment POL-CONTENT-002Sustained targeted abuse, threats, humiliation campaigns and coordinated harassment are prohibited. Ordinary disagreement or criticism is not automatically harassment.Sexual exploitation POL-CONTENT-003Sexual exploitation, non-consensual sexual imagery and sexual content involving minors are prohibited. Some adult sexual content may also be restricted under product-specific rules.Fraud and harmful deception','Scams, impersonation for fraud, credential theft, malicious payment schemes and deceptive activity designed to cause material harm are prohibited.','critical','remove',true,4,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
