insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-COPYRIGHT-002',1,'Copyright','Rights to uploaded material POL-COPYRIGHT-001Users should not upload material they do not have permission or a lawful basis to use. SPIKE should provide an appropriate copyright complaint and takedown process.Repeat infringement','Repeated valid copyright violations may result in escalating account enforcement under applicable law and SPIKE''s terms.','high','restrict',true,2,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
