insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-CORE-002',1,'Core','Source of truth POL-CORE-001Moderation, recommendation safety, notifications, appeals and administrative tools should reference this policy framework and its version rather than maintaining conflicting copies of the rules.Context and proportionality','A detection signal is not automatically proof of a violation. Systems should distinguish clear violations from context-dependent cases and route uncertain cases to review when appropriate.','high','review',true,2,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
