insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-ENFORCEMENT-002',1,'Enforcement','Possible actions POL-ENFORCEMENT-001Warning or educational noticeContent restriction or removalTemporary feature restrictionTemporary account suspensionPermanent account enforcement for severe or repeated violationsAutomatic takedown','Automatic removal should be reserved for rules with sufficiently high confidence. The moderation event should preserve the matched policy ID, policy version, decision source, timestamp and relevant evidence.','critical','remove',true,2,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
