insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-SAFETY-001',1,'Safety','Violence and credible threats','Threats of serious physical harm, targeted incitement of violence and credible plans to harm people are prohibited. Immediate-risk cases may receive priority escalation.','critical','remove',true,1,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
