insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-SAFETY-002',1,'Safety','Violence and credible threats POL-SAFETY-001Threats of serious physical harm, targeted incitement of violence and credible plans to harm people are prohibited. Immediate-risk cases may receive priority escalation.Child safety','Child sexual exploitation and sexualization of minors are prohibited. Suspected material should be handled through the highest-safety moderation path and appropriate escalation procedures.','critical','remove',true,2,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
