insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-TRANSPARENCY-001',1,'Transparency','Decision records','Every enforcement action should retain its policy ID, policy version, action, decision source, timestamp and sufficient evidence for authorized review.','high','allow',true,1,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
