insert into public.spike_policy_rules(id,version,category,title,summary,severity,enforcement,active,priority,body) values ('POL-TRANSPARENCY-003',1,'Transparency','Decision records POL-TRANSPARENCY-001Every enforcement action should retain its policy ID, policy version, action, decision source, timestamp and sufficient evidence for authorized review.User notices POL-TRANSPARENCY-002When content is removed or restricted, the user notification should provide a clear reason and identify the applicable policy category when safe and appropriate to disclose.Administrative accountability','Administrative moderation decisions should be permission-controlled and logged. Privileged tools should not bypass the policy record.','critical','review',true,3,jsonb_build_object('appeal',true)) on conflict(id) do update set version=excluded.version,category=excluded.category,title=excluded.title,summary=excluded.summary,severity=excluded.severity,enforcement=excluded.enforcement,active=excluded.active,priority=excluded.priority,body=excluded.body,updated_at=now();
